const commonSources = [sba, nist];
const commonFaqs = [{ q: 'When should the worker pause?', a: 'Pause for missing evidence, conflicting records, an approval boundary, or a case not covered by the agreed examples.' }, { q: 'What should the manager review?', a: 'Review the source trail, the exception decision, and whether the next owner can act from the completed record.' }];
const commonBrief = ['Work source: the named queue, system, report, or folder supplied by the manager.', 'Done means: required fields are present, evidence is linked, and the next action is dated.', 'Manager approves: money, policy exceptions, sensitive access, deletion, unusual promises, and process changes.'];

export const august17BlogDetails: Record<string, Detail> = {
  'philippines-outsourced-intake-checklist': { updated: '2026-08-17', takeaways: ['A Philippines support intake should reject ambiguity before it becomes rework.', 'Capture the work object, requested outcome, source record, deadline, and decision owner.', 'Use a visible missing-field response instead of guessing.'], fitRows: [{signal:'Complete request',example:'Record, outcome, source, deadline, owner',reason:'The item can be assigned safely'},{signal:'Needs clarification',example:'A message says “please handle this”',reason:'The expected result is unknown'},{signal:'Escalate',example:'Conflicting customer or system records',reason:'A reply could create a commitment'}], sections: [{heading:'Make intake prove the request is ready',paragraphs:['For Philippines-based support, the intake record should identify the customer or work object without copying unnecessary private data. Add the desired outcome, authoritative source, deadline, and named decision owner.','A request that lacks one of those fields is not ready for silent assignment. Return it with the exact missing field and the consequence of waiting, so the owner can answer once rather than through a chain of guesses.']},{heading:'Separate preparation from authority',paragraphs:['Support staff can classify the request, collect context, and draft the next action. They should not infer refunds, policy exceptions, access changes, or customer promises from an incomplete note.','Use a stop state for conflicting records. The escalation should link both sources, state which field disagrees, and identify the manager who can resolve it.']},{heading:'Sample the queue',paragraphs:['Review a few accepted and returned requests each week. Look for repeated missing fields, unclear deadlines, and work sent to the wrong owner.','When the same omission recurs, improve the intake form or example rather than asking the worker to remember another informal rule.']}], brief: ['Role goal: route complete support requests to the correct owner.','Required record: work object, outcome, source, deadline, and decision owner.',...commonBrief.slice(1)], faqs: commonFaqs, sources: commonSources, related: ['philippines-operations-support-sop','outsourced-labor-task-queue-design'] },
  'filipino-admin-recurring-task-register': { updated: '2026-08-17', takeaways: ['A recurring task register records triggers, not just due dates.', 'Name the source and expected output for every Filipino admin task.', 'Make late work explainable without relying on memory.'], fitRows: [{signal:'Ready to repeat',example:'Cadence, trigger, source, output, owner',reason:'The task can survive a calendar change'},{signal:'Weak register',example:'“Check inbox every Friday”',reason:'No finish line or source is named'},{signal:'Escalate',example:'Source is stale or unavailable',reason:'The output may mislead the owner'}], sections: [{heading:'Register the event that starts the work',paragraphs:['A Filipino admin recurring-task register should say what event starts the task: a date, a received file, a weekly meeting, or a system status. “Do weekly admin” is not an actionable trigger.','Add the source location, required fields, expected output, owner, and late rule. This turns a reminder into a handoff another person can inspect.']},{heading:'Design for missed cycles',paragraphs:['When a task is late, record whether the cause was a missing source, unavailable access, an owner decision, or capacity. Do not backfill a report from an unverified assumption.','A manager can then decide whether to recover the cycle, change the cadence, or accept the omission with a dated note.']},{heading:'Retire stale repetition',paragraphs:['Review the register when the business process changes. Remove tasks that no longer produce a useful decision and update examples when the source system changes.','A short monthly review prevents calendar noise from hiding the few recurring controls that matter.']}], brief: ['Role goal: keep recurring admin outputs visible and current.',...commonBrief], faqs: commonFaqs, sources: commonSources, related: ['philippines-admin-assistant-onboarding','outsourced-labor-daily-output-report'] },
  'outsourced-labor-approval-evidence': { updated: '2026-08-17', takeaways: ['An approval packet should make one decision easy to answer.', 'Show the request, source, options, consequence of waiting, and decision question.', 'Preparation must not silently become approval.'], fitRows: [{signal:'Decision-ready',example:'Evidence, options, risk, explicit question',reason:'The owner can decide without reconstruction'},{signal:'Incomplete',example:'A recommendation with no source',reason:'The basis cannot be checked'},{signal:'Escalate',example:'Policy or financial consequence',reason:'Authority belongs to the owner'}], sections: [{heading:'Ask one decision question',paragraphs:['For outsourced labor decisions, an approval packet works best when it asks one bounded question: approve, reject, or request more evidence. Put the relevant source record next to the request rather than linking to an unfiltered folder.','Explain what happens if the decision waits. That distinguishes a real deadline from a preference and helps the owner order competing requests.']},{heading:'Show alternatives honestly',paragraphs:['List the practical options considered and the trade-off each creates. Staff may organize the comparison, but should not present a preferred option as an approved policy.','If the evidence is contradictory, preserve the contradiction in the packet and identify the person who can resolve it.']},{heading:'Keep the decision trail',paragraphs:['Record the decision, date, approver, conditions, and follow-up owner. A later reviewer should be able to tell which facts were known at the time.','Sample packets for missing sources and ambiguous authority before allowing a larger queue.']}], brief: ['Role goal: prepare bounded approval evidence.',...commonBrief], faqs: commonFaqs, sources: commonSources, related: ['outsourced-labor-approval-workflow','outsourced-labor-planning'] },
  'philippines-customer-record-correction': { updated: '2026-08-17', takeaways: ['Correct customer records from an authoritative source, not a plausible message.', 'Preserve the old value and reason when the change matters.', 'Separate evidence collection from permission to edit.'], fitRows: [{signal:'Safe correction',example:'Requested field matches source proof',reason:'The change is traceable'},{signal:'Hold',example:'Two systems disagree',reason:'The correct value is unresolved'},{signal:'Escalate',example:'Identity, payment, or legal field',reason:'The consequence exceeds routine editing'}], sections: [{heading:'Name the field and its authority',paragraphs:['Philippines-based staff handling customer record corrections should identify the exact field, current value, requested value, and authoritative source. A customer email may explain a request without proving the value for every system.','Before editing, compare the source timestamp and identity context. If the source is not current enough for the action, ask the owner for a fresh verification path.']},{heading:'Make the edit reversible',paragraphs:['Preserve the prior value, correction reason, time, and approving owner where the record affects service, identity, or compliance. Avoid overwriting history with a silent change.','Use a limited permission for preparation and a separate approval for sensitive fields.']},{heading:'Review correction patterns',paragraphs:['A weekly sample should distinguish wrong source selection from typing errors and unclear instructions. Each cause needs a different remedy.','Only expand the lane when the reviewer can verify both the source choice and the resulting record.']}], brief: ['Role goal: make traceable customer-record corrections.',...commonBrief], faqs: commonFaqs, sources: commonSources, related: ['philippines-customer-data-handling','filipino-customer-context-handoff'] },
  'filipino-operations-work-intake-priorities': { updated: '2026-08-17', takeaways: ['Rank Filipino operations work by consequence and dependency, not message volume.', 'Make deadlines and reversibility visible.', 'Reserve owner decisions for the cases that change risk or commitments.'], fitRows: [{signal:'Priority input',example:'Impact, deadline, dependency, reversibility',reason:'The queue reflects business consequence'},{signal:'Defer',example:'Urgent-sounding but low-consequence request',reason:'Noise should not displace risk'},{signal:'Escalate',example:'Two high-impact items share one owner',reason:'Only the owner can choose'}], sections: [{heading:'Build a decision rule for the queue',paragraphs:['For Filipino operations staff, a priority order should use the consequence of delay, actual deadline, dependency, and reversibility. “Who asked first” is useful only when the business has explicitly chosen that rule.','Record why an item moved ahead. A short reason makes the queue explainable when a manager reviews the day.']},{heading:'Protect scarce owner decisions',paragraphs:['Some work waits for a customer promise, refund, policy exception, or source clarification. Mark that waiting state instead of disguising it as worker delay.','When two high-impact items compete for the same decision owner, escalate the trade-off with dates and consequences.']},{heading:'Calibrate with real cases',paragraphs:['Compare ordinary, late, and blocked examples against the ranking rule. If reviewers disagree, change the rule or add an example; do not leave the disagreement implicit.','Recheck the queue after a deadline or dependency changes.']}], brief: ['Role goal: maintain a consequence-based operations queue.',...commonBrief], faqs: commonFaqs, sources: commonSources, related: ['outsourced-labor-backlog-triage','philippines-virtual-assistant-task-priorities'] },
  'outsourced-support-sensitive-case-boundary': { updated:'2026-08-17', takeaways:['Support boundaries prevent a helpful reply from becoming an unauthorized promise.','Define triggers, evidence, and the manager who decides.','Treat money, identity, policy, and unusual commitments as explicit holds.'], fitRows:[{signal:'Routine reply',example:'Approved answer with ordinary facts',reason:'The rule is already tested'},{signal:'Manager review',example:'Refund, identity, policy exception',reason:'The response changes risk or authority'},{signal:'Stop',example:'Threat, dispute, or contradictory account',reason:'More context is required'}], sections:[{heading:'List the cases that change the relationship',paragraphs:['An outsourced support lane needs more than a list of common questions. Name the cases where a reply could change money, access, policy, identity, or a customer promise.','For each trigger, state what the worker may collect, what draft they may prepare, and which manager owns the answer.']},{heading:'Require evidence before escalation',paragraphs:['A sensitive-case handoff should include the customer request, verified account context, prior promise, relevant policy, and the exact decision needed. Avoid forwarding a long thread without a summary.','If identity or account ownership is uncertain, pause before exposing details or changing the record.']},{heading:'Review boundary misses',paragraphs:['Sample both escalated cases and cases that stayed in the routine lane. A missed escalation is more important than a slower draft.','Update examples when a new case type appears, and tell staff what remains outside their authority.']}], brief:['Role goal: route sensitive support cases safely',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['filipino-customer-complaint-triage','philippines-support-reply-approval-lane'] },
  'philippines-admin-source-of-truth-map': { updated:'2026-08-17', takeaways:['Every recurring admin output needs a named controlling record.','Record freshness, update ownership, and fallback behavior.','Conflicting sources are a stop condition, not a judgment call.'], fitRows:[{signal:'Mapped field',example:'System, field, owner, freshness',reason:'The record has a clear authority'},{signal:'Fallback',example:'Primary system unavailable',reason:'Recovery is planned'},{signal:'Conflict',example:'Spreadsheet and CRM disagree',reason:'The owner must resolve authority'}], sections:[{heading:'Map fields, not just applications',paragraphs:['A Philippines admin source-of-truth map should name the controlling record for each field in a report or workflow. Saying “use the CRM” is too broad if different fields are maintained elsewhere.','Add the update owner, expected freshness, access needed, and a fallback source. The map should tell the worker what to do when the preferred record is unavailable.']},{heading:'Handle disagreement visibly',paragraphs:['When two sources disagree, preserve both values and identify the field that controls the decision. Do not choose the more convenient spreadsheet without an owner rule.','A manager should resolve a durable authority conflict and record the decision for the next case.']},{heading:'Keep the map current',paragraphs:['Test the map against one ordinary report and one exception. Review it after system, ownership, or process changes.','Stale authority notes create the same risk as stale data: a correct procedure applied to the wrong record still produces a wrong result.']}], brief:['Role goal: maintain an authoritative source map',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['philippines-admin-file-organization','outsourced-labor-source-checklist'] },
  'filipino-research-evidence-handoff': { updated:'2026-08-17', takeaways:['A research handoff connects each material finding to a source and question.','Separate observation, interpretation, and unresolved issue.','A source list without claim links is not usable evidence.'], fitRows:[{signal:'Usable finding',example:'Claim, source, date, limitation',reason:'The next owner can assess it'},{signal:'Weak finding',example:'Summary with a homepage link',reason:'The exact support is unclear'},{signal:'Escalate',example:'Source conflict or missing scope',reason:'The conclusion needs review'}], sections:[{heading:'Write for the decision that follows',paragraphs:['Filipino research staff should receive a business question, not only a keyword. The handoff should state what decision the finding will inform and which claims are material.','For each claim, record the named publication or dataset, relevant page or table, retrieval date, scope, and limitation.']},{heading:'Keep fact and interpretation apart',paragraphs:['A source may report an observation while the handoff infers a possible implication. Label those layers so a manager can challenge the interpretation without losing the evidence.','When two reputable sources use different definitions, explain the difference instead of averaging the claims.']},{heading:'Make the next check reproducible',paragraphs:['Include the search boundary, included period, exclusions, and open question. Another reviewer should be able to repeat the check without guessing what the researcher meant.','Sample handoffs for traceability and relevance before expanding the research lane.']}], brief:['Role goal: deliver decision-linked research evidence',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['filipino-research-fact-checking-workflow','philippines-research-assistant-brief'] },
  'outsourced-labor-queue-aging-review': { updated:'2026-08-17', takeaways:['Queue age is a symptom; identify whether work waits on capacity, evidence, or a decision.','Inspect the oldest item in each waiting group.','Do not solve owner latency by adding worker volume.'], fitRows:[{signal:'Actionable age',example:'Age plus waiting reason and owner',reason:'The remedy can target the bottleneck'},{signal:'Misleading metric',example:'One average age number',reason:'Different waits are hidden'},{signal:'Escalate',example:'Old item risks a promise',reason:'A decision is time-sensitive'}], sections:[{heading:'Break age into waiting reasons',paragraphs:['An outsourced labor queue review should group open items by age and reason: missing input, owner decision, external dependency, worker capacity, or correction. The same age can require opposite remedies.','Inspect the oldest item in each group, not only the average. Record its next action and accountable owner.']},{heading:'Separate handling from waiting',paragraphs:['A worker may complete a draft quickly while the item remains open for approval. Keep handling time and decision latency distinct so the review does not blame the wrong lane.','If the oldest item risks a customer promise, escalate with the exact date and unresolved decision.']},{heading:'Use the review to change the system',paragraphs:['Look for repeated waiting reasons and remove the cause: add a required intake field, clarify approval ownership, or plan coverage.','Recheck whether the intervention changes the distribution of old items, not only the headline average.']}], brief:['Role goal: explain queue age and assign the right remedy',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['outsourced-labor-backlog-triage','outsourced-labor-escalation-response-time'] },
  'philippines-support-reply-approval-lane': { updated:'2026-08-17', takeaways:['Open live replies by class, not by optimism.','Approve ordinary examples and define the cases that remain drafts.','Track new reply classes as review work.'], fitRows:[{signal:'Approved class',example:'Known question and tested reply',reason:'The boundary is observable'},{signal:'Draft only',example:'New wording or unusual context',reason:'The response needs review'},{signal:'Escalate',example:'Money, identity, policy, promise',reason:'The owner must decide'}], sections:[{heading:'Start with reply classes',paragraphs:['A Philippines support approval lane should list the ordinary customer questions that have approved answers. Define the facts the worker must verify before using each class.','Keep a new question as a draft until a reviewer confirms the wording, evidence, and escalation path.']},{heading:'Put approval next to the draft',paragraphs:['The reviewer should see the customer context, source record, proposed response, and reason the class applies. A bare draft encourages approval by momentum.','Do not let approval of wording imply approval of a refund, policy exception, or unverified promise.']},{heading:'Measure safe expansion',paragraphs:['Track reply classes, correction reasons, and escalations. A growing number of classes is not success if the examples are inconsistent.','Expand only after ordinary and edge cases produce the same decision under review.']}], brief:['Role goal: move approved support replies through a bounded lane',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['filipino-customer-support-reply-library','outsourced-support-sensitive-case-boundary'] },
  'filipino-admin-calendar-access-boundary': { updated:'2026-08-17', takeaways:['Calendar delegation needs view, edit, invite, and disclosure rules.','Private event details are not required for every scheduling action.','Time zones and confidential meetings need explicit examples.'], fitRows:[{signal:'Safe scheduling',example:'Free/busy view and approved event types',reason:'The task can be completed with limited detail'},{signal:'Owner action',example:'Confidential or high-stakes meeting',reason:'Context and relationship matter'},{signal:'Stop',example:'Unclear attendee or private event',reason:'Disclosure risk is unresolved'}], sections:[{heading:'Define the smallest useful calendar access',paragraphs:['For Filipino admin support, decide separately whether the worker may view availability, edit ordinary events, invite attendees, move meetings, or disclose details. “Calendar access” hides too many permissions.','Give examples for private appointments, customer calls, interviews, and time-zone conversions.']},{heading:'Make scheduling decisions visible',paragraphs:['A scheduling note should preserve the request, constraints, time zone, attendees, and unresolved choice. The worker can propose times without deciding which confidential commitment takes priority.','Require owner review for a meeting whose purpose or attendee list is sensitive.']},{heading:'Review access when the role changes',paragraphs:['Check permissions when a calendar lane expands or ends. Remove access promptly and keep a dated record of the change.','Sample reschedules and invitations for accidental disclosure, wrong time zones, and missing confirmation.']}], brief:['Role goal: schedule within explicit calendar boundaries',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['philippines-virtual-assistant-calendar-controls','filipino-admin-calendar-handoff'] },
  'outsourced-labor-work-completion-standard': { updated:'2026-08-17', takeaways:['“Done” should be a verifiable record, not a status word.','Specify required fields, source link, exception note, and next action.','A reviewer should know what remains without reopening the whole task.'], fitRows:[{signal:'Complete',example:'Output, source, status, exception, next action',reason:'The handoff is independently checkable'},{signal:'Returned',example:'Output lacks source or context',reason:'The result cannot be trusted'},{signal:'Escalate',example:'Completion depends on approval',reason:'The item is not worker-owned'}], sections:[{heading:'Define done at the record level',paragraphs:['An outsourced labor completion standard should name the evidence that proves an item is complete. For a report, that may be the source population and period; for a support case, it may be the verified answer and dated follow-up.','Write the fields into the task template and show one accepted and one returned example.']},{heading:'Keep exceptions attached',paragraphs:['A completed record can still have an exception. State what differed, what was done, and who must decide next. Do not hide a blocked dependency behind a green status.','Separate worker completion from final owner approval when the outcome affects money, policy, or a customer commitment.']},{heading:'Use completion reviews to improve instructions',paragraphs:['Sample records for accuracy, completeness, timeliness, and handoff usefulness. Categorize returns so the standard improves rather than becoming a longer checklist.','The best standard makes the next action obvious to someone who did not perform the work.']}], brief:['Role goal: produce records that another owner can verify',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['outsourced-labor-handoff-quality-check','outsourced-labor-quality-scorecard'] },
  'philippines-vendor-followup-escalation': { updated:'2026-08-17', takeaways:['Vendor follow-up should preserve the request and promised response, not just send reminders.','Record operational impact and the escalation date.','Staff should not negotiate unauthorized commitments.'], fitRows:[{signal:'Routine follow-up',example:'Known request and agreed contact',reason:'The next message is bounded'},{signal:'Owner decision',example:'Changed terms or missed commitment',reason:'The business consequence is material'},{signal:'Escalate',example:'No response before impact date',reason:'The dependency now threatens work'}], sections:[{heading:'Track the dependency as a case',paragraphs:['For Philippines operations, a vendor follow-up record should include request date, exact item requested, source correspondence, promised response, and operational impact. This makes a reminder useful to someone covering the queue.','Add the date that an owner must intervene if no response arrives.']},{heading:'Keep the message within authority',paragraphs:['Staff can ask for status, restate agreed requirements, and report a missed date. They should not promise payment, accept changed terms, or commit the business to a new schedule without approval.','Escalate with the vendor evidence and the decision the owner must make.']},{heading:'Review dependency patterns',paragraphs:['Look for repeated late responses, unclear requests, and single points of contact. The fix may be a better intake record, backup vendor contact, or owner-level renegotiation.','Keep vendor facts separate from assumptions about why a response is late.']}], brief:['Role goal: keep vendor dependencies visible and bounded',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['filipino-vendor-follow-up-tracker','outsourced-labor-escalation-response-time'] },
  'filipino-customer-context-handoff': { updated:'2026-08-17', takeaways:['A support handoff should preserve verified context without copying a whole private thread.','Name what was promised and what remains unresolved.','The next owner needs an action and an accountable name.'], fitRows:[{signal:'Useful handoff',example:'Request, facts, action, promise, owner',reason:'The next specialist can continue safely'},{signal:'Too thin',example:'“Customer is waiting”',reason:'No action or evidence is named'},{signal:'Sensitive',example:'Identity or complaint context',reason:'Access and escalation need review'}], sections:[{heading:'Compress history into decisions',paragraphs:['A Filipino customer-support handoff should state the customer request, verified facts, action already taken, unresolved question, promised next update, and accountable owner. It should not make the next specialist search a long conversation for the decision.','Link only the relevant record and protect details that the next owner does not need.']},{heading:'Distinguish promise from intention',paragraphs:['Record what was actually promised, by whom, and for what date. A draft idea is not a customer commitment. If the promise is impossible, escalate it rather than quietly changing the date.','Sensitive complaints, identity questions, and policy exceptions need the named manager in the handoff.']},{heading:'Review handoffs at the next action',paragraphs:['Sample whether the recipient could act without asking the same question again. Repeated clarification indicates a missing field or unclear ownership.','Keep the handoff current when the customer replies or the promised update changes.']}], brief:['Role goal: transfer customer context with a clear next action',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['filipino-customer-support-reply-library','outsourced-labor-shift-handoff'] },
  'outsourced-labor-missing-information-loop': { updated:'2026-08-17', takeaways:['A blocked work item should ask for one named missing field at a time.','Explain why the field matters and who can supply it.','Set a fallback or escalation date so the request does not disappear.'], fitRows:[{signal:'Good request',example:'Missing field, reason, provider, date',reason:'The owner can answer directly'},{signal:'Noise',example:'“Need more details”',reason:'The blocker is not actionable'},{signal:'Escalate',example:'No answer before a consequence date',reason:'Waiting now has a business impact'}], sections:[{heading:'Turn a blocker into a precise request',paragraphs:['For outsourced labor, a missing-information loop should identify the exact field, why the work cannot proceed, who can provide it, and the date requested. This prevents repeated broad questions.','Keep the original work item open with a blocked reason rather than creating duplicate tasks in several inboxes.']},{heading:'Use a safe fallback',paragraphs:['If an owner cannot answer, define whether the item can be deferred, narrowed, or escalated. Never fill a consequential field with a plausible guess merely to clear the queue.','A manager should choose the fallback when it changes a customer promise, financial record, or policy outcome.']},{heading:'Measure recurring blockers',paragraphs:['Review blocked reasons by process and owner. Repeated omissions may justify a better intake form, source map, or example.','Close the loop by recording the answer where the next worker will find it.']}], brief:['Role goal: resolve missing information without hidden assumptions',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['outsourced-labor-blocked-task-review','philippines-outsourced-intake-checklist'] },
  'philippines-admin-report-reconciliation': { updated:'2026-08-17', takeaways:['Reconcile a report to its source population, period, filters, and exclusions.','Investigate mismatches before changing the number.', 'A report preparer can explain evidence without owning the business conclusion.'], fitRows:[{signal:'Comparable',example:'Same population, period, filters, exclusions',reason:'The totals can be meaningfully compared'},{signal:'Investigate',example:'Stale field or changed filter',reason:'The mismatch has a traceable cause'},{signal:'Escalate',example:'Material unexplained variance',reason:'The manager must decide what to report'}], sections:[{heading:'Define what the report counts',paragraphs:['A Philippines admin report reconciliation starts with scope: which records belong, which period is measured, which filters apply, and which exclusions are intentional. A total is not meaningful until those boundaries match the source.','Record the source query or population reference and the time the data was retrieved.']},{heading:'Classify the mismatch',paragraphs:['Separate missing records, duplicate records, stale fields, changed definitions, and calculation errors. Each category points to a different correction.','Do not “fix” a total by editing the report until the source and calculation path are understood.']},{heading:'Present uncertainty honestly',paragraphs:['A manager-ready reconciliation should show matched totals, unresolved variance, likely cause, and next check. The preparer can recommend investigation without turning an estimate into a fact.','Sample reconciliations after source or filter changes.']}], brief:['Role goal: deliver traceable reconciled admin reports',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['outsourced-labor-quality-scorecard','outsourced-labor-daily-output-report'] },
  'filipino-operations-change-request': { updated:'2026-08-17', takeaways:['Capture process ideas from Filipino operations staff without granting change authority by default.','Describe the observed problem and example cases.', 'Test a bounded change before replacing the current rule.'], fitRows:[{signal:'Useful proposal',example:'Problem, cases, change, risk, owner',reason:'The decision can be evaluated'},{signal:'Needs evidence',example:'“This process is bad”',reason:'The issue cannot be reproduced'},{signal:'Owner review',example:'Change affects policy or access',reason:'The current authority must decide'}], sections:[{heading:'Record the problem before the solution',paragraphs:['A Filipino operations change request should start with the observed failure: where work stalled, which examples were affected, and what evidence shows the pattern. A proposed shortcut is not yet a process improvement.','State the expected benefit and the risk if the change is wrong.']},{heading:'Use a bounded test',paragraphs:['Define the smallest queue, time window, and reviewer for a trial. Keep the current instruction available until the owner accepts the evidence.','Changes involving access, money, policy, deletion, or customer promises require explicit owner approval before testing.']},{heading:'Close the loop with the proposer',paragraphs:['Record the decision, rationale, and resulting instruction. If the idea is declined, explain the constraint so the same proposal does not recur without new evidence.','Review whether the change improved quality and handoff time, not only speed.']}], brief:['Role goal: route evidence-led process changes',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['outsourced-labor-process-improvement-loop','filipino-staff-review-calibration'] },
  'outsourced-support-case-reopen-rules': { updated:'2026-08-17', takeaways:['Reopen a support case for a defined reason, not every new message.','Separate new evidence, missed promise, customer response, and unresolved outcome.', 'Assign the next owner when a case reopens.'], fitRows:[{signal:'Reopen',example:'New evidence or missed promise',reason:'The prior outcome is no longer complete'},{signal:'Link only',example:'Unrelated customer question',reason:'A new case preserves clarity'},{signal:'Escalate',example:'Complaint or policy consequence',reason:'The manager owns the response'}], sections:[{heading:'Name the reopen reasons',paragraphs:['For outsourced support, define separate reasons for reopening: new evidence, a customer response, a missed promise, or an unresolved outcome. Each reason should create a different next action.','Do not reopen a closed record simply because a related topic arrived; link a new case when the original outcome remains complete.']},{heading:'Preserve the prior decision',paragraphs:['Keep the original resolution and explain what changed. This lets the next owner distinguish a genuine reversal from a request that was already answered.','If the new evidence changes money, policy, identity, or a promise, route it to the approving owner before replying.']},{heading:'Review false closures',paragraphs:['Sample reopened cases for the reason code and handoff quality. Repeated reopenings may indicate a weak completion standard or an overbroad closure rule.','Use the pattern to improve examples, not to pressure staff into keeping unresolved work closed.']}], brief:['Role goal: reopen support cases for explicit reasons',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['outsourced-labor-work-completion-standard','outsourced-support-sensitive-case-boundary'] },
  'philippines-remote-work-contingency-notes': { updated:'2026-08-17', takeaways:['Continuity notes should show the last trusted state, not just contact details.','Record paused work, access dependencies, backup ownership, and customer promises at risk.', 'Recovery needs a return-to-normal check.'], fitRows:[{signal:'Ready note',example:'Queue state, access, owner, risk, next check',reason:'A backup can resume safely'},{signal:'Weak note',example:'“Team unavailable”',reason:'No work state is known'},{signal:'Escalate',example:'Critical work or promise at risk',reason:'The owner must prioritize recovery'}], sections:[{heading:'Capture the last trusted state',paragraphs:['For Philippines remote work continuity, record which queues were open, which items were complete, what evidence was saved, and which access dependency failed. A contact list alone cannot tell a backup what is safe to resume.','Name the backup owner and the customer or vendor promise at risk, if any.']},{heading:'Pause before recreating work',paragraphs:['During a disruption, preserve the known state and avoid duplicate updates from several people. Mark uncertain items for verification when access returns.','The owner decides which commitments can be renegotiated and which work must be recovered first.']},{heading:'Verify recovery',paragraphs:['A return-to-normal check should confirm access, queue ownership, duplicate work, pending escalations, and the next customer update.','Review the note after the incident and update the procedure using observed gaps, not imagined detail.']}], brief:['Role goal: document safe continuity and recovery state',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['philippines-backup-coverage-schedule','philippines-remote-team-coverage-notes'] },
  'filipino-staff-review-calibration': { updated:'2026-08-17', takeaways:['Calibration uses the same examples and rubric across reviewers.','Discuss why cases differ, not only whether they passed.', 'Record unclear rules for correction.'], fitRows:[{signal:'Calibrated',example:'Reviewers agree on ordinary and exception cases',reason:'Feedback is more consistent'},{signal:'Discuss',example:'Same output gets different ratings',reason:'The rubric needs interpretation'},{signal:'Escalate',example:'Rule conflicts with policy',reason:'The owner must clarify authority'}], sections:[{heading:'Choose representative cases',paragraphs:['A Filipino staff review calibration session should include an ordinary case, a near-miss, and an exception. Reviewers apply the same rubric independently before comparing results.','The purpose is not to force agreement on every judgment; it is to expose which rule or example produces the difference.']},{heading:'Explain the rating',paragraphs:['Discuss source use, completeness, timing, escalation judgment, and handoff quality. “Good job” or “be more careful” does not teach a repeatable standard.','When reviewers disagree because the case is outside scope, record that boundary rather than inventing a new rule live.']},{heading:'Turn learning into a controlled update',paragraphs:['Keep the accepted interpretation and example with the instructions. Assign an owner and date for any policy clarification.','Recalibrate after a meaningful process change or a pattern of inconsistent outcomes.']}], brief:['Role goal: make review standards consistent and teachable',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['filipino-staff-performance-feedback','outsourced-labor-quality-calibration'] },
  'outsourced-labor-task-boundary-audit': { updated:'2026-08-17', takeaways:['Audit a proposed task against evidence, access, authority, consequence, and review capacity.','A repeatable task is not automatically a safe task.', 'Expand scope only when the manager can still see exceptions.'], fitRows:[{signal:'Fit',example:'Clear inputs, narrow access, visible output',reason:'The lane can be reviewed'},{signal:'Redesign',example:'Unclear authority or hidden dependency',reason:'The task is not ready'},{signal:'Reject or hold',example:'Sensitive consequence exceeds review',reason:'Risk is not controlled'}], sections:[{heading:'Test the task before adding it',paragraphs:['Before expanding outsourced labor, compare the proposed task with the current SOP, source quality, data exposure, consequence of error, approval line, and manager review time.','Ask what evidence proves completion and what happens when the normal example does not apply.']},{heading:'Look for hidden owner work',paragraphs:['A task may appear routine while requiring frequent policy choices, private context, or customer commitments. Count those escalations as part of the design, not as worker failure.','If review capacity is lower than exception volume, narrow the lane or redesign the input.']},{heading:'Record the scope decision',paragraphs:['Document the accepted boundary, excluded cases, access change, sample plan, and owner who can reverse the expansion.','Reaudit after the source system, policy, or consequence changes.']}], brief:['Role goal: approve only reviewable outsourced work lanes',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['outsourced-labor-role-expansion-test','outsourced-labor-planning'] },
  'philippines-content-approval-handoff': { updated:'2026-08-17', takeaways:['A content handoff should carry the brief, evidence, draft state, metadata, and approver together.','Support staff can prepare publishing inputs without becoming final publishers.', 'Open questions must remain visible.'], fitRows:[{signal:'Ready for review',example:'Brief, audience, sources, draft, metadata, approver',reason:'The owner can review the whole decision'},{signal:'Return',example:'Draft has claims without source notes',reason:'Editorial risk is unresolved'},{signal:'Escalate',example:'Unclear audience or public claim',reason:'The owner must set direction'}], sections:[{heading:'Bundle the editorial decision',paragraphs:['For Philippines-based support handling content operations, the handoff should state the audience, question, intended outcome, source notes, draft status, metadata, open questions, and named approver. A finished paragraph is not a finished publication.','Keep evidence next to the claim it supports so the reviewer does not reconstruct the research from a general link list.']},{heading:'Protect the publishing boundary',paragraphs:['Staff may format, organize, fact-check, and route a draft under an approved brief. The owner decides whether the public claim, date, canonical route, and final wording are ready.','Do not use metadata fields to hide unresolved editorial questions or unsupported results.']},{heading:'Review the handoff, not just the prose',paragraphs:['Sample whether the approver could identify what changed, what remains open, and which source supports each material statement.','Update the handoff template when a recurring omission appears, while keeping topic-specific analysis in each article.']}], brief:['Role goal: route complete content approval packets',...commonBrief], faqs:commonFaqs, sources:commonSources, related:['philippines-content-operations-workflow','filipino-research-evidence-handoff'] },
};
